# Initially generated by GitHub Copilot.
"""Exports write."""

from pathlib import Path

import uxlc_misc.uxlc_utils_html as uxlc_utils_html
import uxlc_fois.fois_mark_grammar_2_html as fois_mark_grammar_2_html
import uxlc_fois.fois_mark_grammar_html as fois_mark_grammar_html
import uxlc_paths

_DETAIL_FILENAME_BY_KEY = {
    "kq": "foi-kq.html",
    "mark-grammar": "foi-mark-grammar.html",
    "mark-grammar-2": "foi-mark-grammar-2.html",
}
_PAGE_LABEL_BY_KEY = {
    "mark-grammar-2": "mark grammar 2",
}
_KQ_FIELD_HEADERS = ("bcvp", "k1", "k2", "q1", "q2")


def _count_str(value):
    return f"{value:,}"


def write(fois, json_output_paths):
    """Write HTML pages for the FOI catalog."""
    _write_index(fois)
    if kq_catalog := fois.get("kq"):
        _write_kq_page(kq_catalog, json_output_paths["kq"])
    if mark_catalog := fois.get("mark-grammar"):
        fois_mark_grammar_html.write(
            mark_catalog,
            json_output_paths["mark-grammar"],
            _detail_path("mark-grammar"),
        )
    if mark_grammar_2_catalog := fois.get("mark-grammar-2"):
        fois_mark_grammar_2_html.write(
            mark_grammar_2_catalog,
            json_output_paths["mark-grammar-2"],
            _detail_path("mark-grammar-2"),
        )


def _detail_path(foi_key):
    return uxlc_paths.fois_pages_dir() / _DETAIL_FILENAME_BY_KEY[foi_key]


def _write_index(fois):
    rows = [uxlc_utils_html.table_row_of_headers(("page", "summary"))]
    for foi_key, catalog in sorted(fois.items()):
        rows.append(_index_row(foi_key, catalog))
    body_contents = _body_wrapper(
        [
            uxlc_utils_html.heading_level_1("UXLC features of interest"),
            uxlc_utils_html.para(
                "This is an HTML view of the FOI catalog generated by"
                " MAM-basics/py/main_fois.py."
            ),
            uxlc_utils_html.table(rows, {"class": "border-collapse limited-width"}),
        ]
    )
    _write_html(
        "UXLC features of interest",
        uxlc_paths.fois_pages_dir() / "index.html",
        body_contents,
    )


def _index_row(foi_key, catalog):
    detail_filename = _DETAIL_FILENAME_BY_KEY.get(foi_key)
    page_label = _PAGE_LABEL_BY_KEY.get(foi_key, foi_key)
    if detail_filename is None:
        page_cell = uxlc_utils_html.table_datum(page_label)
    else:
        page_cell = uxlc_utils_html.table_datum(
            uxlc_utils_html.anchor(page_label, {"href": detail_filename})
        )
    summary_cell = uxlc_utils_html.table_datum(_summary_for_catalog(foi_key, catalog))
    return uxlc_utils_html.table_row((page_cell, summary_cell))


def _summary_for_catalog(foi_key, catalog):
    if foi_key == "kq":
        type_counts = catalog["type-counts"]
        total_cases = sum(type_counts.values())
        exotic_cases = len(catalog["exotic-cases-flat"])
        return (
            f"{_count_str(total_cases)} total cases; "
            f"{_count_str(exotic_cases)} exotic cases"
        )
    if foi_key == "mark-grammar":
        return fois_mark_grammar_html.summary(catalog)
    if foi_key == "mark-grammar-2":
        return fois_mark_grammar_2_html.summary(catalog)
    return "HTML summary not implemented"


def _write_kq_page(kq_catalog, json_output_path):
    body_contents = _body_wrapper(
        [
            uxlc_utils_html.heading_level_1("kq (UXLC features of interest)"),
            uxlc_utils_html.para(
                [
                    uxlc_utils_html.anchor("FOI index", {"href": "index.html"}),
                    " | ",
                    *_json_link_contents(json_output_path),
                ]
            ),
            uxlc_utils_html.para(
                "Each kNqM label counts a contiguous kere/qere group with N ketiv atoms and M qere atoms."
            ),
            uxlc_utils_html.para(
                f"There are {_count_str(sum(kq_catalog['type-counts'].values()))} "
                f"total kq cases; "
                f"{_count_str(len(kq_catalog['exotic-cases-flat']))} are listed below "
                f"as exotic."
            ),
            uxlc_utils_html.heading_level_2("Counts by type"),
            _kq_counts_table(kq_catalog),
            *_kq_sections(kq_catalog),
        ]
    )
    _write_html("kq (UXLC features of interest)", _detail_path("kq"), body_contents)


def _kq_counts_table(kq_catalog):
    rows = [uxlc_utils_html.table_row_of_headers(("type", "count", "details"))]
    for kq_type, count in kq_catalog["type-counts"].items():
        rows.append(_kq_count_row(kq_type, count, kq_catalog))
    return uxlc_utils_html.table(rows, {"class": "border-collapse limited-width"})


def _kq_count_row(kq_type, count, kq_catalog):
    cases = kq_catalog["exotic-cases-by-type"].get(kq_type, [])
    if cases:
        detail_contents = uxlc_utils_html.anchor(
            f"{_count_str(len(cases))} exotic cases",
            {"href": f"#{_section_id(kq_type)}"},
        )
    elif kq_type == "k1q1":
        detail_contents = "Counted only; not listed below"
    else:
        detail_contents = "0 exotic cases"
    return uxlc_utils_html.table_row_of_data(
        (_kq_type_label(kq_type), _count_str(count), detail_contents)
    )


def _kq_sections(kq_catalog):
    sections = []
    for kq_type, cases in kq_catalog["exotic-cases-by-type"].items():
        sections.extend(_kq_section(kq_type, cases))
    return sections


def _kq_section(kq_type, cases):
    heading = uxlc_utils_html.heading_level_2(
        f"{_kq_type_label(kq_type)} ({_count_str(len(cases))} cases)",
        {"id": _section_id(kq_type)},
    )
    return [heading, _kq_cases_table(cases)]


def _kq_cases_table(cases):
    rows = [uxlc_utils_html.table_row_of_headers(_KQ_FIELD_HEADERS)]
    rows.extend(_kq_case_row(case_dic) for case_dic in cases)
    return uxlc_utils_html.table(rows, {"class": "border-collapse limited-width"})


def _kq_case_row(case_dic):
    row_cells = []
    for field_name in _KQ_FIELD_HEADERS:
        cell_value = case_dic[field_name] or ""
        if field_name == "bcvp":
            row_cells.append(uxlc_utils_html.table_datum(cell_value))
            continue
        attr = {"lang": "hbo", "dir": "rtl"} if cell_value else None
        row_cells.append(uxlc_utils_html.table_datum(cell_value, attr))
    return uxlc_utils_html.table_row(tuple(row_cells))


def _kq_type_label(kq_type):
    numk = int(kq_type[1])
    numq = int(kq_type[3])
    return f"{kq_type} ({numk} ketiv, {numq} qere)"


def _section_id(kq_type):
    return f"intro-{kq_type}"


def _json_link_contents(json_output_path):
    return [
        "JSON catalog: ",
        uxlc_utils_html.anchor(
            _json_basename(json_output_path),
            {"href": _json_basename(json_output_path)},
        ),
    ]


def _json_basename(json_output_path):
    # Path, not PurePosixPath: the catalog paths are now absolute, and on Windows a
    # PurePosixPath sees no separator in a backslashed one and returns the whole string
    # as the "name" -- which would land in the page as an absolute path in an href.
    return Path(json_output_path).name


def _body_wrapper(contents):
    style = "max-width: 50rem; margin-left: auto; margin-right: auto"
    return [uxlc_utils_html.div(contents, {"style": style})]


def _write_html(title, out_path, body_contents):
    write_ctx = uxlc_utils_html.WriteCtx(title, out_path)
    uxlc_utils_html.write_html_to_file(body_contents, write_ctx, "../")
